            "initialCode": "// [TEACHING SIMULATION — Effect Cleanup Lifecycle Simulation]\nclass EffectLifecycleRunner {\n  constructor() {\n    this.cleanupFn = null;\n  }\n  runEffect(effectSetup) {\n    // 1. Run previous cleanup if one exists:\n    if (this.cleanupFn) {\n      console.log('[Cleanup] Running previous effect cleanup...');\n      this.cleanupFn();\n    }\n    // 2. Run new effect setup:\n    console.log('[Setup] Running new effect...');\n    this.cleanupFn = effectSetup();\n  }\n  unmount() {\n    if (this.cleanupFn) {\n      console.log('[Teardown] Running final cleanup on unmount...');\n      this.cleanupFn();\n      this.cleanupFn = null;\n    }\n  }\n}\n\nconst runner = new EffectLifecycleRunner();\nrunner.runEffect(() => {\n  console.log('  Subscribed to Chat Room #1');\n  return () => console.log('  Unsubscribed from Chat Room #1');\n});\nrunner.runEffect(() => {\n  console.log('  Subscribed to Chat Room #2');\n  return () => console.log('  Unsubscribed from Chat Room #2');\n});\nrunner.unmount();",
