            "initialCode": "// [TEACHING SIMULATION — Teaching Model: Route Table with Wildcard Fallback]\nfunction resolveRoute(routes, pathname) {\n  for (const route of routes) {\n    if (route.pattern === pathname) {\n      return { view: route.component, status: 200 };\n    }\n  }\n  const wildcard = routes.find(r => r.pattern === '*');\n  return wildcard ? { view: wildcard.component, status: 404 } : { view: 'GenericNotFound', status: 404 };\n}\n\nconst routes = [\n  { pattern: '/home', component: 'HomeView' },\n  { pattern: '/dashboard', component: 'DashboardView' },\n  { pattern: '*', component: 'NotFoundView' }\n];\n\nconsole.log(JSON.stringify(resolveRoute(routes, '/dashboard')));\nconsole.log(JSON.stringify(resolveRoute(routes, '/non-existent-page')));",
