            "filename": "deadlock_retry_sim.js",
            "initialCode": "// [TEACHING SIMULATION — Transaction Retry on 40001 / 40P01]\nasync function executeWithRetry(simulateAttemptFn, maxRetries = 3) {\n  let attempt = 0;\n  while (attempt < maxRetries) {\n    attempt++;\n    const res = simulateAttemptFn(attempt);\n    if (res.success) return { success: true, attempts: attempt };\n    if (res.code === '40001' || res.code === '40P01') {\n      // Backoff and retry\n      continue;\n    }\n    return { success: false, error: res.error };\n  }\n  return { success: false, error: 'MAX_RETRIES_EXCEEDED' };\n}\nconst sim = (attempt) => attempt === 1 ? { success: false, code: '40P01' } : { success: true };\nexecuteWithRetry(sim).then(r => console.log(JSON.stringify(r)));",
