          "code": "// Simulation: Domain Service vs Application Service\n// 1. Domain Service: business calculation; prefer infrastructure independence for testability\nclass TaxCalculationDomainService {\n  calculateTax(subtotalCents, stateCode) {\n    const rates = { CA: 0.0825, NY: 0.08, TX: 0.0625 };\n    const rate = rates[stateCode] || 0.05;\n    return Math.round(subtotalCents * rate);\n  }\n}\n\n// 2. Application Service: orchestrates use case, persistence, and external calls\nclass PlaceOrderApplicationService {\n  constructor(orderRepo, paymentGateway, taxDomainService) {\n    this.orderRepo = orderRepo;\n    this.paymentGateway = paymentGateway;\n    this.taxDomainService = taxDomainService;\n  }\n  async execute(orderId, stateCode) {\n    const order = await this.orderRepo.findById(orderId);\n    const taxCents = this.taxDomainService.calculateTax(order.calculateTotalCents(), stateCode);\n    const totalWithTax = order.calculateTotalCents() + taxCents;\n    await this.paymentGateway.charge(order.customerId, totalWithTax);\n    order.status = 'PAID';\n    await this.orderRepo.save(order);\n    return { orderId, totalWithTax, status: order.status };\n  }\n}\n\nconsole.log('Domain vs Application Service separated successfully.');",
