            "initialCode": "// Simulation: Heartbeat Sweeper & ws.terminate() vs ws.close()\nclass MockSocket {\n  constructor(id) { this.id = id; this.isAlive = true; this.state = 'OPEN'; }\n  ping() { if (this.isAlive) { this.isAlive = false; } }\n  pong() { this.isAlive = true; }\n  close() { this.state = 'CLOSING'; } // Stalls if peer unreachable\n  terminate() { this.state = 'DESTROYED'; } // Immediate destruction\n}\n\nfunction runSweep(sockets) {\n  sockets.forEach(s => {\n    if (!s.isAlive) {\n      s.terminate();\n    } else {\n      s.isAlive = false;\n      s.ping();\n    }\n  });\n}\n\nconst s1 = new MockSocket('client_healthy');\nconst s2 = new MockSocket('client_zombie');\ns2.isAlive = false; // Simulated unresponded ping\nrunSweep([s1, s2]);\nconsole.log('Healthy Socket:', s1.state, '| isAlive:', s1.isAlive);\nconsole.log('Zombie Socket:', s2.state);",
