            "filename": "day-86-b1_sim.js",
            "initialCode": "// Simulation: In-Memory Partition Failure vs Redis Pub/Sub Cross-Server Broadcast\nclass MockServerNode {\n  constructor(nodeId) { this.nodeId = nodeId; this.localSockets = new Map(); }\n  connect(userId, socket) { this.localSockets.set(userId, socket); }\n  broadcastInMemory(msg) {\n    return Array.from(this.localSockets.keys()).map(uid => ({ deliveredTo: uid, node: this.nodeId }));\n  }\n}\n\nconst srv1 = new MockServerNode('srv_1');\nconst srv2 = new MockServerNode('srv_2');\nsrv1.connect('user_A', {});\nsrv2.connect('user_B', {});\n\nconsole.log('Server 1 In-Memory Broadcast:', srv1.broadcastInMemory('hello'));\nconsole.log('Notice: user_B on Server 2 received 0 messages! Out-of-process bus is required.');",
