            "initialCode": "// Simulation: Connection Pool Context Scoping (SET vs SET LOCAL)\nclass PooledConnection {\n  constructor() { this.sessionVars = {}; }\n  setGlobal(k, v) { this.sessionVars[k] = v; } // Persists across transactions!\n  async runTransaction(tenantId, fn) {\n    const backup = { ...this.sessionVars };\n    this.sessionVars['app.current_tenant_id'] = tenantId; // SET LOCAL\n    try {\n      return await fn();\n    } finally {\n      this.sessionVars = backup; // COMMIT/ROLLBACK automatically clears SET LOCAL\n    }\n  }\n}\n\nconst conn = new PooledConnection();\nawait conn.runTransaction('tenant_alpha', () => {\n  console.log('Inside Tx Context:', conn.sessionVars['app.current_tenant_id']);\n});\nconsole.log('After Tx Completed (Pool Reused):', conn.sessionVars['app.current_tenant_id'] || 'CLEAN (NO LEAK)');",
