            "type": "runnable_code",
            "filename": "day-93-b2_sim.js",
            "initialCode": "// Demonstration of Gerard Meszaros Test Double Taxonomy\n// 1. Dummy: Unused parameter\nconst dummyLogger = { log: () => {} };\n\n// 2. Stub: Canned answer\nconst exchangeRateStub = { getRate: (curr) => 1.25 };\n\n// 3. Spy: Records invocation history\nclass EmailSpy {\n  constructor() { this.sent = []; }\n  send(to, body) { this.sent.push({ to, body }); }\n}\n\n// 4. Fake: In-memory working substitute\nclass InMemoryUserRepo {\n  constructor() { this.users = new Map(); }\n  async save(user) { this.users.set(user.id, { ...user }); }\n  async findById(id) { return this.users.get(id) || null; }\n}\n\nconsole.log('Stub Rate:', exchangeRateStub.getRate('EUR'));\nconst spy = new EmailSpy();\nspy.send('alice@corp.internal', 'Welcome');\nconsole.log('Spy Sent Count:', spy.sent.length);",
