          "diagnosisMap": {
            "0": {
              "misconceptionId": "MC_FS_GIT_BISECT_LINEAR_ASSUMPTION",
              "errorExplanation": "Sequential checking is O(n); git bisect halves the candidate search space on every iteration, achieving O(log n) bound.",
              "recoveryPath": {
                "simplerExplanation": "Binary search cuts candidate commits in half at each test. log2(1024) = 10 steps.",
                "guidedFixPrompt": "Leverage automated bisect with `git bisect run` to find regressions across hundreds of commits in seconds."
              }
            }
          }
