            "initialCode": "// IAM Policy Evaluation Engine Simulation\nconst policy = {\n  statements: [\n    { effect: 'Allow', action: 's3:GetObject', resource: 'arn:aws:s3:::app-bucket/*' },\n    { effect: 'Deny', action: 's3:*', resource: 'arn:aws:s3:::app-bucket/confidential/*' }\n  ]\n};\n\nfunction evaluateIAM(action, resource) {\n  // 1. Explicit Deny overrides all\n  const isDeny = policy.statements.some(s => s.effect === 'Deny' && s.resource.endsWith('/*') && resource.startsWith(s.resource.replace('/*', '')));\n  if (isDeny) return 'DENY (Explicit Deny Precedence)';\n  // 2. Explicit Allow\n  const isAllow = policy.statements.some(s => s.effect === 'Allow' && s.action === action);\n  return isAllow ? 'ALLOW' : 'DENY (Implicit Default)';\n}\n\nconsole.log('Read public file:', evaluateIAM('s3:GetObject', 'arn:aws:s3:::app-bucket/public/img.png'));\nconsole.log('Read secret file:', evaluateIAM('s3:GetObject', 'arn:aws:s3:::app-bucket/confidential/keys.env'));",
