            "filename": "day-108-b3_sim.js",
            "initialCode": "// Simulation: stale-while-revalidate HTTP Header Semantics at the Edge\nfunction evaluateEdgeCache(cachedItem, nowMs) {\n  const ageSec = (nowMs - cachedItem.cachedAt) / 1000;\n  if (ageSec <= cachedItem.maxAge) {\n    return { response: cachedItem.body, status: 'HIT', backgroundFetch: false };\n  }\n  if (ageSec <= cachedItem.maxAge + cachedItem.staleWhileRevalidate) {\n    return {\n      response: cachedItem.body,\n      status: 'STALE_HIT',\n      backgroundFetch: true,\n      note: 'Serving stale payload immediately while asynchronously revalidating origin in background'\n    };\n  }\n  return { response: null, status: 'MISS', backgroundFetch: true, note: 'Synchronously fetching fresh payload from origin' };\n}\n\nconst item = { body: 'data_v1', cachedAt: 1000, maxAge: 60, staleWhileRevalidate: 300 };\nconsole.log('Age 30s:', evaluateEdgeCache(item, 31000).status);\nconsole.log('Age 120s:', evaluateEdgeCache(item, 121000));\nconsole.log('Age 400s:', evaluateEdgeCache(item, 401000).status);",
